sys_script_fix.script:
updateTable('sn_vdr_risk_asmt_assessment');
updateTable('sn_vdr_risk_asmt_vdr_tiering_assessment');
updateTable('sn_vdr_risk_asmt_repeating_assessment');
updateTable('sn_vdr_risk_asmt_issue');
updateTable('sn_vdr_risk_asmt_task');

function updateTable(table) {
    var gr = new GlideRecord(table);
    gr.addNullQuery('applies_to');
    gr.addNotNullQuery('vendor');
    gr.setValue('applies_to', 'vendor');
    gr.updateMultiple();
}
